export function validateAllRepositoryScope(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "kind": {
          if (item !== "ALL") fail(contract, `${path}.kind`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.kind`, "expected string");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateApiErrorResponse(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "code")) fail(contract, `${path}.code`, "missing required property");
  if (!Object.hasOwn(record, "kind")) fail(contract, `${path}.kind`, "missing required property");
  if (!Object.hasOwn(record, "message")) fail(contract, `${path}.message`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "code": {
          if (typeof item !== "string") fail(contract, `${path}.code`, "expected string");
          break;
        }
        case "details": {
          if (!isRecord(item)) fail(contract, `${path}.details`, "expected object");
          break;
        }
        case "kind": {
          validateReference("ErrorKind", validateErrorKind, item, `${path}.kind`, contract, refStack);
          break;
        }
        case "message": {
          if (typeof item !== "string") fail(contract, `${path}.message`, "expected string");
          break;
        }
        case "request_id": {
          validateUnion(contract, `${path}.request_id`, [
            () => {
              if (typeof item !== "string") fail(contract, `${path}.request_id`, "expected string");
            },
            () => {
              if (item !== null) fail(contract, `${path}.request_id`, "expected null");
            },
          ]);
          break;
        }
        case "retryable": {
          if (typeof item !== "boolean") fail(contract, `${path}.retryable`, "expected boolean");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}

export function validateAssessedRuntimeSafetyProof(value: unknown, path: string, contract: string, refStack: Set<string>): void {
  validateUnion(contract, path, [
    () => {
      validateReference("ProvenRuntimeSafetyProof", validateProvenRuntimeSafetyProof, value, path, contract, refStack);
    },
    () => {
      validateReference("DegradedRuntimeSafetyProof", validateDegradedRuntimeSafetyProof, value, path, contract, refStack);
    },
  ]);
}

export function validateAttemptsExhaustedPlanRetryDecisionEvidence(value: unknown, path: string, contract: string): void {
  if (!isRecord(value)) fail(contract, path, "expected object");
  const record = value as JsonRecord;
  if (!Object.hasOwn(record, "exit_code")) fail(contract, `${path}.exit_code`, "missing required property");
  if (!Object.hasOwn(record, "policy_reason")) fail(contract, `${path}.policy_reason`, "missing required property");
  for (const [key, item] of Object.entries(record)) {
    switch (key) {
        case "disposition": {
          if (item !== "ATTEMPTS_EXHAUSTED") fail(contract, `${path}.disposition`, "did not match required constant");
          if (typeof item !== "string") fail(contract, `${path}.disposition`, "expected string");
          break;
        }
        case "exit_code": {
          if (typeof item !== "number" || !Number.isFinite(item)) fail(contract, `${path}.exit_code`, "expected finite number");
          if (!Number.isInteger(item)) fail(contract, `${path}.exit_code`, "expected integer");
          break;
        }
        case "policy_reason": {
          if (typeof item !== "string") fail(contract, `${path}.policy_reason`, "expected string");
          if ((item as string).length < 1) fail(contract, `${path}.policy_reason`, "must contain at least 1 characters");
          if ((item as string).length > 240) fail(contract, `${path}.policy_reason`, "must contain at most 240 characters");
          break;
        }
      default: {
        fail(contract, `${path}.${key}`, "unexpected property");
      }
    }
  }
}
